import './BookCard.css';
import type { BookStatus } from '../../types';

interface BookCardProps {
  title: string;
  author: string;
  status: BookStatus;
}

const STATUS_LABELS: Record<BookStatus, string> = {
  read: 'Read',
  reading: 'Reading',
  'to-read': 'To Read',
};

export function BookCard({ title, author, status }: BookCardProps): JSX.Element {
  return (
    <article className="book-card">
      <h2 className="book-card-title">{title}</h2>
      <p className="book-card-author">{author}</p>
      <span className={`book-card-badge book-card-badge--${status}`}>
        {STATUS_LABELS[status]}
      </span>
    </article>
  );
}
